The code snippet provided here is part of the modular exponentiation module found in the HACK@DAC'21 Openpiton System-on-Chip (SoC), specifically within the RSA peripheral. Modular exponentiation, denoted as "a^b mod n," is a crucial operation in the RSA public/private key encryption. In RSA encryption, where 'c' represents ciphertext, 'm' stands for a message, and 'd' corresponds to the private key, the decryption process is carried out using this modular exponentiation as follows: m = c^d mod n, where 'n' is the result of multiplying two large prime numbers.
(bad code)

module mod_exp #(
    parameter WIDTH = 32  
)(
    input  wire                 clk,           
    input  wire                 rst,           
    input  wire [WIDTH-1:0]     base_in,       
    input  wire [WIDTH-1:0]     exponent_in,   
    input  wire [WIDTH-1:0]     modulus_in,    
    output reg  [WIDTH-1:0]     result_out     
);
    reg [WIDTH-1:0] base_reg, exponent_reg, result_reg, mask_reg, base_next, exponent_next;
    reg [2:0] state;

    localparam IDLE   = 3'b000;
    localparam UPDATE = 3'b001;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result_reg   <= 1;  
            mask_reg     <= 1;
            base_reg     <= 0;
            exponent_reg <= 0;
            state        <= IDLE;
        end else begin
            case (state)
                UPDATE: begin
                    if (exponent_reg != 0) begin
                        if (exponent_reg[0]) begin
                            result_reg <= (result_reg * base_reg) % modulus_in; 
                        end 
                        base_reg     <= (base_reg * base_reg) % modulus_in;    
                        exponent_reg <= exponent_reg >> 1;                     
                        state        <= UPDATE;                                
                    end else begin
                        result_out   <= result_reg;
                        state        <= IDLE;                                 
                    end
                end
                default: begin
                    result_reg   <= 1;
                    mask_reg     <= 1;
                    base_reg     <= base_in;
                    exponent_reg <= exponent_in;
                    state        <= UPDATE;
                end
            endcase
        end
    end
endmodule

