        if (~rst_ni) begin
            state_q <= Idle;
            pass_check <= 1'b0;
            miss_pass_check_cnt_q <= 2'b00; 
        end else begin
            state_q <= state_d;
            miss_pass_check_cnt_q <= miss_pass_check_cnt_d; 
        end
    end

    always @(*) begin
        case (state_q)
            PassChkValid: begin
                if (hashValid) begin
                    if (exp_hash == pass_hash) begin
                        pass_check = 1'b1; 
                        miss_pass_check_cnt_d = 2'b00; 
                    end else begin
                        pass_check = 1'b0; 
                        miss_pass_check_cnt_d = miss_pass_check_cnt_q + 1; 
                        if (miss_pass_check_cnt_q == 2'b11) begin
                            state_d = Lock; 
                        end else begin
                            state_d = Idle; 
                        end
                    end
                end else begin
                    state_d = PassChkValid; 
                end
            end
            Lock: begin
                pass_check = 1'b0; 
                state_d = Lock; 
